create or replace function public.sc_complete_lyric(p_lyric_id uuid) returns uuid language plpgsql security invoker set search_path = '' as $$
declare lyric public.sc_lyrics%rowtype; song_id uuid;
begin
  select * into lyric from public.sc_lyrics where id = p_lyric_id and user_id = (select auth.uid()) for update;
  if not found then raise exception 'Textový dokument nebyl nalezen.' using errcode = 'P0002'; end if;
  update public.sc_lyrics set status = 'complete', completed_at = now() where id = lyric.id;
  select id into song_id from public.sc_songs where source_lyric_id = lyric.id and user_id = (select auth.uid()) limit 1;
  if song_id is null then
    insert into public.sc_songs (user_id, album_id, source_lyric_id, title, style_prompt, lyrics, notes, cover_path, completed_at)
    values ((select auth.uid()), lyric.album_id, lyric.id, lyric.title, lyric.style_prompt, lyric.lyrics, lyric.notes, lyric.cover_path, now()) returning id into song_id;
  else
    update public.sc_songs set album_id = lyric.album_id, title = lyric.title, style_prompt = lyric.style_prompt, lyrics = lyric.lyrics, notes = lyric.notes, cover_path = lyric.cover_path, completed_at = now() where id = song_id;
  end if;
  return song_id;
end;
$$;

create or replace function public.sc_set_version_state(p_version_id uuid, p_final boolean) returns void language plpgsql security invoker set search_path = '' as $$
declare target_song_id uuid;
begin
  select song_id into target_song_id from public.sc_audio_versions where id = p_version_id and user_id = (select auth.uid()) for update;
  if target_song_id is null then raise exception 'Zvuková verze nebyla nalezena.' using errcode = 'P0002'; end if;
  update public.sc_audio_versions set is_primary = false, is_final = false where song_id = target_song_id and user_id = (select auth.uid());
  update public.sc_audio_versions set is_primary = true, is_final = p_final where id = p_version_id and user_id = (select auth.uid());
end;
$$;

grant execute on function public.sc_complete_lyric(uuid) to authenticated;
grant execute on function public.sc_set_version_state(uuid, boolean) to authenticated;
